contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmt)); require(depAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= depAmt);

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        c.Deposit{value: depAmt}(); if (__ESBMC_reverted()) return;

        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(balAfter == balBefore + depAmt);
    }

    receive() external payable {}
}

